import java.util.ArrayList;
import java.util.Scanner;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;

public class DS02 {
    private static Scanner scanner = new Scanner(System.in);
    private static ProductNode headNode = null;

    public static void main(String[] args) {
        System.out.println("是否要从文件中读入链表数据(y or n)？");
        if("y".equals(scanner.next())) {
            readFromFile();
        } else {
            headNode = new ProductNode();
        }
        while(true) {
            menu();
        }
    }

    private static void readFromFile() {
        try {
            ObjectInputStream input = new ObjectInputStream(new FileInputStream(new File("headnode")));
            headNode = (ProductNode) input.readObject();
            input.close();
        } catch(Exception e) {
            System.out.println("读入数据失败！已创建空的头节点");
            headNode = new ProductNode();
        }
    }

    private static void menu() {
        scanner = new Scanner(System.in);
        System.out.println();
        System.out.println();
        System.out.println("***********************");
        System.out.println("*1. 进货              *");
        System.out.println("*2. 提货              *");
        System.out.println("*3. 查询              *");
        System.out.println("*4. 更新              *");
        System.out.println("*5. 结束              *");
        System.out.println("***********************");
        System.out.print("请输入选择：");
        int choice = 0;
        try {
            choice = scanner.nextInt();
        } catch(Exception e) {
            System.out.println("输入有误，请重新输入！");
            return;
        }
        System.out.println();
        System.out.println();
        switch(choice) {
            case 1:
                addProduct();
                break;
            case 2:
                reduceProduct();
                break;
            case 3:
                searchProduct();
                break;
            case 4:
                updateProduct();
                break;
            case 5:
                exitSystem();
                break;
            default:
                System.out.println("输入有误，请重新输入！");
                break;
        }
    }

    private static void addProduct() {
        scanner = new Scanner(System.in);
        System.out.print("请输入进货的货物名称：");
        String name = scanner.nextLine();
        System.out.print("请输入进货的货物品牌：");
        String brand = scanner.nextLine();
        System.out.print("请输入进货的货物单价：");
        float price = scanner.nextFloat();
        System.out.print("请输入进货的货物数量：");
        int amount = scanner.nextInt();
        if(headNode.getNextNode() == null) {
            headNode.setNextNode(new ProductNode(name, brand, price, amount));
        } else {
            ProductNode currentNode = headNode;
            ProductNode targetNode = null;
            while(currentNode.getNextNode() != null) {
                currentNode = currentNode.getNextNode();
                if(name.equals(currentNode.getName()) && brand.equals(currentNode.getBrand())) {
                    if(price == currentNode.getPrice()) {
                        targetNode = currentNode;
                        break;
                    } else {
                        System.out.println("当前货物品牌和名称已存在，单价不符，请修改单价后再添加！");
                        return;
                    }
                }
            }
            if(targetNode != null) {
                targetNode.setAmount(targetNode.getAmount() + amount);
            } else {
                ProductNode previousNode = headNode;
                currentNode = headNode.getNextNode();
                while(previousNode.getNextNode() != null) {
                    if(currentNode.getPrice() >= price) {
                        previousNode.setNextNode(new ProductNode(name, brand, price, amount));
                        previousNode = previousNode.getNextNode();
                        previousNode.setNextNode(currentNode);
                        return;
                    }
                    previousNode = previousNode.getNextNode();
                    currentNode = currentNode.getNextNode();
                }
                previousNode.setNextNode(new ProductNode(name, brand, price, amount));
            }
        }
    }

    private static void reduceProduct() {
        if(headNode.getNextNode() == null) {
            System.out.println("当前无任何货物！");
            return;
        }
        scanner = new Scanner(System.in);
        System.out.print("请输入提货的货物名称：");
        String name = scanner.nextLine();
        System.out.print("请输入提货的货物品牌：");
        String brand = scanner.nextLine();
        System.out.print("请输入提货的货物数量：");
        int amount = scanner.nextInt();
        ProductNode currentNode = headNode.getNextNode();
        ProductNode previousNode = headNode;
        ProductNode targetNode = null;
        while(currentNode != null) {
            if(name.equals(currentNode.getName())) {
                if(brand.equals(currentNode.getBrand())) {
                    targetNode = currentNode;
                    break;
                }
                currentNode = currentNode.getNextNode();
                previousNode = previousNode.getNextNode();
            } else {
                currentNode = currentNode.getNextNode();
                previousNode = previousNode.getNextNode();
            }
        }
        if(targetNode == null) {
            System.out.println("查无此货物！");
            return;
        }
        if(targetNode.getAmount() > amount) {
            targetNode.setAmount(targetNode.getAmount() - amount);
        } else if(targetNode.getAmount() == amount) {
            currentNode = currentNode.getNextNode();
            previousNode.setNextNode(currentNode);
        } else {
            System.out.println("该货物数量不足，请查询后重新操作！");
        }
    }

    private static void searchProduct() {
        System.out.println("***********************");
        System.out.println("*1. 输出全部           *");
        System.out.println("*2. 按照名称           *");
        System.out.println("*3. 按照品牌           *");
        System.out.println("***********************");
        System.out.print("请输入选择：");
        int choice = scanner.nextInt();
        while(choice != 1 && choice != 2 && choice != 3) {
            System.out.println("选择有误，请重新输入：");
            choice = scanner.nextInt();
        }
        switch(choice) {
            case 1:
                outputAll();
                break;
            case 2:
                searchByName();
                break;
            case 3:
                searchByBrand();
                break;
            default:
                break;
        }
    }

    private static void outputAll() {
        ProductNode currentNode = headNode.getNextNode();
        if(currentNode == null) {
            System.out.println("当前无任何货物信息！");
            return;
        }
        while(currentNode != null) {
            System.out.printf("%8s\t%8s\t%6.2f\t%5d\n", currentNode.getName(), currentNode.getBrand(), currentNode.getPrice(), currentNode.getAmount());
            currentNode = currentNode.getNextNode();
        }
    }

    private static void searchByName() {
        scanner = new Scanner(System.in);
        System.out.print("请输入你要查询的货物名称：");
        String name = scanner.nextLine();
        ProductNode currentNode = headNode.getNextNode();
        System.out.println("查询结果：");
        while(currentNode != null) {
            if(currentNode.getName().equals(name)) {
                System.out.printf("%8s\t%8s\t%6.2f\t%5d\n", currentNode.getName(), currentNode.getBrand(), currentNode.getPrice(), currentNode.getAmount());
            }
            currentNode = currentNode.getNextNode();
        }
    }

    private static void searchByBrand() {
        scanner = new Scanner(System.in);
        System.out.print("请输入你要查询的货物品牌：");
        String brand = scanner.nextLine();
        ProductNode currentNode = headNode.getNextNode();
        System.out.println("查询结果：");
        while(currentNode != null) {
            if(currentNode.getBrand().equals(brand)) {
                System.out.printf("%8s\t%8s\t%6.2f\t%5d\n", currentNode.getName(), currentNode.getBrand(), currentNode.getPrice(), currentNode.getAmount());
            }
            currentNode = currentNode.getNextNode();
        }
    }

    private static void updateProduct() {
        scanner = new Scanner(System.in);
        System.out.println("请输入要更新的商品的名称：");
        String name = scanner.nextLine();
        System.out.println("请输入要更新的商品的品牌：");
        String brand = scanner.nextLine();
        ProductNode targetNode = null;
        ProductNode currentNode = headNode.getNextNode();
        ProductNode previousNode = headNode;
        while(currentNode != null) {
            if(currentNode.getName().equals(name) && currentNode.getBrand().equals(brand)) {
                targetNode = currentNode;
                break;
            }
            previousNode = previousNode.getNextNode();
            currentNode = currentNode.getNextNode();
        }
        if(targetNode == null) {
            System.out.println("无此商品，请核对之后在修改！");
            return;
        }
        previousNode.setNextNode(currentNode.getNextNode());
        System.out.println("当前查询到的记录信息：");
        System.out.printf("%8s\t%8s\t%6.2f\t%5d\n", targetNode.getName(), targetNode.getBrand(), targetNode.getPrice(), targetNode.getAmount());
        System.out.print("请输入修改的字段名称（名称，品牌，单价，数量）：");
        String field = scanner.nextLine();
        switch(field) {
            case "名称":
                System.out.print("请输入修改后的内容：");
                targetNode.setName(scanner.nextLine());
                break;
            case "品牌":
                System.out.print("请输入修改后的内容：");
                targetNode.setBrand(scanner.nextLine());
                break;
            case "单价":
                System.out.print("请输入修改后的内容：");
                targetNode.setPrice(scanner.nextFloat());
                break;
            case "数量":
                System.out.print("请输入修改后的内容：");
                targetNode.setAmount(scanner.nextInt());
                break;
            default:
                System.out.println("输入错误，请检查字段名称！");
                break;
        }
        insertProduct(targetNode);
    }

    private static void insertProduct(ProductNode targetNode) {
        float price = targetNode.getPrice();
        if(headNode.getNextNode() == null) {
            headNode.setNextNode(targetNode);
        } else {
            ProductNode previousNode = headNode;
            ProductNode currentNode = headNode.getNextNode();
            while(currentNode != null) {
                if(currentNode.getPrice() >= price) {
                    previousNode.setNextNode(targetNode);
                    targetNode.setNextNode(currentNode);
                    return;
                }
                previousNode = previousNode.getNextNode();
                currentNode = currentNode.getNextNode();
            }
            previousNode.setNextNode(targetNode);
            targetNode.setNextNode(null);
        }
    }

    private static void exitSystem() {
        saveToFile();
        System.exit(0);
    }

    private static void saveToFile() {
        try {
            ObjectOutputStream output = new ObjectOutputStream(new FileOutputStream(new File("headnode")));
            output.writeObject(headNode);
            output.close();
        } catch(Exception e) {
            System.out.println("写入文件失败！");
            e.printStackTrace();
        }
    }
}

class ProductNode implements Serializable{
    private static final long serialVersionUID = 1L;

    private String name;
    private String brand;
    private float price;
    private int amount;
    private ProductNode nextNode;

    public ProductNode(String name, String brand, float price, int amount) {
        this.name = name;
        this.brand = brand;
        this.price = price;
        this.amount = amount;
    }

    public ProductNode() {

    }

    public void setName(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public void setBrand(String brand) {
        this.brand = brand;
    }

    public String getBrand() {
        return brand;
    }

    public void setPrice(float price) {
        this.price = price;
    }

    public float getPrice() {
        return price;
    }

    public void setAmount(int amount) {
        this.amount = amount;
    }

    public int getAmount() {
        return amount;
    }

    public void setNextNode(ProductNode nextNode) {
        this.nextNode = nextNode;
    }

    public ProductNode getNextNode() {
        return nextNode;
    }
}

import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class TestDS02 {
    static int failures = 0;

    static void check(String label, boolean cond) {
        System.out.println((cond ? "PASS " : "FAIL ") + label);
        if(!cond) failures++;
    }

    static Field f(String name) throws Exception {
        Field fld = DS02.class.getDeclaredField(name);
        fld.setAccessible(true);
        return fld;
    }

    static Method m(String name, Class<?>... types) throws Exception {
        Method mtd = DS02.class.getDeclaredMethod(name, types);
        mtd.setAccessible(true);
        return mtd;
    }

    // Run a private static method with given stdin; returns captured stdout.
    static String run(String method, String stdin, Class<?>... types) throws Exception {
        return runWithArgs(method, stdin, new Object[0], types);
    }

    static String runWithArgs(String method, String stdin, Object[] args, Class<?>... types) throws Exception {
        InputStream oldIn = System.in;
        PrintStream oldOut = System.out;
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        try {
            System.setIn(new ByteArrayInputStream(stdin.getBytes(StandardCharsets.UTF_8)));
            System.setOut(new PrintStream(buf, true, "UTF-8"));
            // reset static scanner so methods that reuse it (searchProduct) get fresh input
            f("scanner").set(null, new Scanner(System.in));
            m(method, types).invoke(null, args);
        } finally {
            System.setIn(oldIn);
            System.setOut(oldOut);
        }
        return buf.toString("UTF-8");
    }

    static ProductNode head() throws Exception {
        return (ProductNode) f("headNode").get(null);
    }

    static void setHead(ProductNode n) throws Exception {
        f("headNode").set(null, n);
    }

    static List<String> rows() throws Exception {
        List<String> out = new ArrayList<>();
        ProductNode cur = head().getNextNode();
        while(cur != null) {
            out.add(cur.getName() + "/" + cur.getBrand() + "/" + cur.getPrice() + "/" + cur.getAmount());
            cur = cur.getNextNode();
        }
        return out;
    }

    static ProductNode node(String name, String brand, float price, int amount) {
        return new ProductNode(name, brand, price, amount);
    }

    static ProductNode chain(ProductNode... nodes) {
        ProductNode head = new ProductNode();
        ProductNode cur = head;
        for(ProductNode n : nodes) { cur.setNextNode(n); cur = n; }
        return head;
    }

    public static void main(String[] args) throws Exception {
        // ---------- build a baseline list (mirrors headnode data file) ----------
        setHead(chain(node("xiaomi", "mix3", 2899f, 100),
                      node("doggy", "mix2", 4000f, 49),
                      node("xiaomi", "mix2", 5000f, 30)));

        // outputAll
        String out = run("outputAll", "");
        check("outputAll prints 3 rows sorted by price",
              out.contains("mix3") && out.contains("doggy") && out.contains("2899.00")
              && out.indexOf("2899") < out.indexOf("4000") && out.indexOf("4000") < out.indexOf("5000"));

        // searchByName
        out = run("searchByName", "xiaomi\n");
        int hits = out.split("xiaomi", -1).length - 1;
        check("searchByName xiaomi -> 2 rows", hits == 2 && out.contains("查询结果"));

        // searchByBrand
        out = run("searchByBrand", "mix2\n");
        check("searchByBrand mix2 -> doggy + xiaomi rows",
              out.contains("doggy") && (out.split("mix2", -1).length - 1) >= 2);

        // addProduct: brand-new product inserted in sorted position (3999 between 2899 and 4000)
        out = run("addProduct", "huawei\np30\n3999\n8\n");
        check("addProduct inserts new product sorted by price",
              rows().toString().equals("[xiaomi/mix3/2899.0/100, huawei/p30/3999.0/8, doggy/mix2/4000.0/49, xiaomi/mix2/5000.0/30]"));

        // addProduct: same name+brand+price -> amount accumulates
        run("addProduct", "huawei\np30\n3999\n12\n");
        check("addProduct same product accumulates amount",
              rows().toString().equals("[xiaomi/mix3/2899.0/100, huawei/p30/3999.0/20, doggy/mix2/4000.0/49, xiaomi/mix2/5000.0/30]"));

        // addProduct: same name+brand but different price -> rejected
        out = run("addProduct", "huawei\np30\n4999\n5\n");
        check("addProduct conflicting price rejected",
              out.contains("单价不符") && rows().size() == 4);

        // addProduct: new cheapest product goes to front
        run("addProduct", "cheap\nstuff\n999\n1\n");
        check("addProduct inserts cheapest at head",
              rows().get(0).equals("cheap/stuff/999.0/1") && rows().size() == 5);

        // reduceProduct: partial reduce
        run("reduceProduct", "cheap\nstuff\n1\n");
        check("reduceProduct exact amount removes node",
              rows().size() == 4 && !rows().toString().contains("cheap"));

        // reduceProduct: partial
        run("reduceProduct", "huawei\np30\n5\n");
        check("reduceProduct partial subtracts amount", rows().get(1).equals("huawei/p30/3999.0/15"));

        // reduceProduct: insufficient stock
        out = run("reduceProduct", "huawei\np30\n99\n");
        check("reduceProduct insufficient amount keeps node",
              out.contains("数量不足") && rows().get(1).equals("huawei/p30/3999.0/15"));

        // reduceProduct: nonexistent
        out = run("reduceProduct", "nosuch\nthing\n1\n");
        check("reduceProduct missing product reports 查无此货物", out.contains("查无此货物"));

        // reduceProduct on empty list
        setHead(chain());
        out = run("reduceProduct", "a\nb\n1\n");
        check("reduceProduct empty list reports 当前无任何货物", out.contains("当前无任何货物"));

        // updateProduct: change price of xiaomi/mix3 2899 -> 4500, list must stay sorted
        setHead(chain(node("xiaomi", "mix3", 2899f, 100),
                      node("doggy", "mix2", 4000f, 49),
                      node("xiaomi", "mix2", 5000f, 30)));
        out = run("updateProduct", "xiaomi\nmix3\n单价\n4500\n");
        check("updateProduct price re-sorts list",
              rows().toString().equals("[doggy/mix2/4000.0/49, xiaomi/mix3/4500.0/100, xiaomi/mix2/5000.0/30]"));

        // updateProduct: change name
        out = run("updateProduct", "doggy\nmix2\n名称\ncat\n");
        check("updateProduct name field", rows().get(0).equals("cat/mix2/4000.0/49"));

        // updateProduct: change amount
        run("updateProduct", "cat\nmix2\n数量\n60\n");
        check("updateProduct amount field", rows().get(0).equals("cat/mix2/4000.0/60"));

        // updateProduct: missing product
        out = run("updateProduct", "ghost\nx\n名称\ny\n");
        check("updateProduct missing product reports 无此商品", out.contains("无此商品"));

        // insertProduct on empty list
        setHead(chain());
        runWithArgs("insertProduct", "", new Object[]{ node("solo", "one", 100f, 1) }, ProductNode.class);
        check("insertProduct into empty list", rows().toString().equals("[solo/one/100.0/1]"));

        // insertProduct appends most expensive at tail
        runWithArgs("insertProduct", "", new Object[]{ node("big", "one", 999f, 2) }, ProductNode.class);
        check("insertProduct appends at tail", rows().toString().equals("[solo/one/100.0/1, big/one/999.0/2]"));

        // persistence round trip: saveToFile writes "headnode" in CWD, readFromFile reads it back
        setHead(chain(node("xiaomi", "mix3", 2899f, 100),
                      node("doggy", "mix2", 4000f, 49)));
        File cwd = new File(".").getCanonicalFile();
        File dataFile = new File(cwd, "headnode");
        if(dataFile.exists()) dataFile.delete();
        run("saveToFile", "");
        check("saveToFile creates headnode file", dataFile.exists());
        setHead(chain()); // wipe in-memory list
        run("readFromFile", "");
        check("readFromFile restores saved list",
              rows().toString().equals("[xiaomi/mix3/2899.0/100, doggy/mix2/4000.0/49]"));

        // readFromFile with missing/corrupt file -> empty head node, no crash
        dataFile.delete();
        setHead(null);
        out = run("readFromFile", "");
        check("readFromFile missing file falls back to empty head",
              out.contains("读入数据失败") && head() != null && head().getNextNode() == null);

        // menu dispatch: invalid numeric choice
        setHead(chain());
        out = run("menu", "9\n");
        check("menu invalid choice reports 输入有误", out.contains("输入有误"));

        // menu dispatch: non-numeric input
        out = run("menu", "abc\n");
        check("menu non-numeric input handled", out.contains("输入有误"));

        // searchProduct submenu: invalid then valid choice, then outputAll on empty list
        out = run("searchProduct", "7\n1\n");
        check("searchProduct re-prompts on invalid choice",
              out.contains("选择有误") && out.contains("当前无任何货物信息"));

        System.out.println(failures == 0 ? "ALL TESTS PASSED" : failures + " TEST(S) FAILED");
        System.exit(failures == 0 ? 0 : 1);
    }
